+<script lang="ts">
+import {
+  defineComponent,
+  PropType,
+  ref,
+  nextTick,
+  watch,
+  reactive,
+  computed,
+} from "vue";
+import { useI18n } from "vue-i18n";
+import { Label } from "../types";
+import { NPopover } from "naive-ui";
+import { isReservedLabel } from "../utils";
+
+type LocalState = {
+  isAdding: boolean;
+  text: string;
+  error: string | undefined;
+  changed: boolean;
+};
+
+const MAX_VALUE_LENGTH = 63;
+
+export default defineComponent({
+  name: "AddLabelValue",
+  components: { NPopover },
+  props: {
+    label: {
+      type: Object as PropType<Label>,
+      required: true,
+    },
+  },
+  emits: ["add"],
+  setup(props, { emit }) {
+    const { t } = useI18n();
+    const input = ref<HTMLInputElement>();
+    const state = reactive<LocalState>({
+      isAdding: false,
+      text: "",
+      error: undefined,
+      changed: false,
+    });
+
+    const reserved = computed(() => isReservedLabel(props.label));
+
+    const toggleAdding = () => {
+      if (isReservedLabel(props.label)) return;
+      state.isAdding = !state.isAdding;
+    };
+
+    const validate = () => {
+      const v = state.text.trim();
+      if (!v) {
+        // can't be empty
+        state.error = t("label.error.value-necessary");
+      } else if (props.label.valueList.includes(v)) {
+        // must be unique
+        state.error = t("label.error.value-duplicated");
+      } else if (v.length > MAX_VALUE_LENGTH) {
+        // max length exceeded
+        state.error = t("label.error.max-length-exceeded", {
+          len: MAX_VALUE_LENGTH,
+        });
+      } else {
+        // ok
+        state.error = undefined;
+      }
+      return !state.error;
+    };
+
+    watch(
+      () => state.text,
+      () => {
+        state.changed = true;
+        validate();
+      }
+    );
+
+    const cancel = () => {
+      state.isAdding = false;
+      state.text = "";
+    };
+
+    const tryAdd = () => {
+      if (state.error) {
+        return;
+      }
+      const v = state.text.trim();
+      emit("add", v);
+      cancel();
+    };
+
+    watch(
+      () => state.isAdding,
+      (isAdding) => {
+        if (isAdding) {
+          // reset input state
+          validate();
+          state.changed = false;
+          // auto focus if possible
+          nextTick(() => input.value?.focus());
+        }
+      }
+    );
+
+    return { state, reserved, toggleAdding, tryAdd, cancel, input };
+  },
+});
+</script>
+
