+  @apply cursor-not-allowed bg-control-bg;
+}
+.textfield {
+  @apply rounded px-2 py-0 text-sm w-32;
+}
+.textfield.error {
+  @apply border-error focus:ring-error focus:border-error;
+}
+.cancel {
+  @apply text-error;
+}
+.save {
+  @apply text-success;
+}
+</style>

