+        if (state.tab === "standard") return "w-160";
+        return "w-192";
+      }
+    });
+
+    return {
+      wrapperClass,
+      state,
+      isAlterSchema,
+      isTenantProject,
+      environmentList,
+      databaseList,
+      standardProjectDatabaseList,
+      tenantProjectDatabaseList,
+      allowGenerateMultiDb,
+      generateMultDb,
+      allowGenerateTenant,
+      generateTenant,
+      selectDatabase,
+      cancel,
+    };
+  },
+});
+</script>

